// ===== CONFIGURAÇÃO: edite aqui =====
const CONFIG = {
  email_naty: 'COLOQUE_O_EMAIL_DA_NATY@gmail.com',
  // Quem pode mandar pedidos ao robô pelo WhatsApp: DDI + DDD + número, só dígitos (ex.: '5511987654321').
  // Mensagem de qualquer outro número é ignorada sem resposta.
  whatsapp_autorizados: ['COLOQUE_O_NUMERO_DA_NATY'],
  whatsapp_phone_number_id: 'COLOQUE_O_ID_DO_NUMERO', // Meta → app → WhatsApp → Configuração da API
  // Recebem o convite do evento e os lembretes por e-mail, além da Naty. Ex.: ['joao@empresa.com']
  emails_equipe: [],
  calendario_id: 'primary',       // ou o ID de um calendário dedicado
  duracao_padrao_horas: 2,        // usada quando o pedido não diz a hora de término
  fuso: 'America/Sao_Paulo',
};
// ====================================

// Celular brasileiro antigo pode chegar do WhatsApp sem o 9 ("551187654321" em vez de "5511987654321").
// Compara as duas formas para a lista de autorizados funcionar nos dois casos.
const formas = n => {
  const d = String(n || '').replace(/\D/g, '');
  const f = new Set([d]);
  if (/^55\d{2}9\d{8}$/.test(d)) f.add(d.slice(0, 4) + d.slice(5));
  if (/^55\d{2}\d{8}$/.test(d)) f.add(d.slice(0, 4) + '9' + d.slice(4));
  return f;
};
const autorizado = numero => {
  const de = formas(numero);
  return CONFIG.whatsapp_autorizados.some(a => [...formas(a)].some(x => de.has(x)));
};

const j = $input.first().json;
let texto = '', origem, referencia, canal, responder_para = '', encaminhada = false, erro = '';

if (j.messaging_product === 'whatsapp' || j.messages || j.statuses) {
  // Veio do WhatsApp (nó "WhatsApp Trigger": um item por mensagem recebida)
  const m = (j.messages || [])[0];
  if (!m) return [];                     // aviso de entrega/leitura, não é mensagem
  if (!autorizado(m.from)) return [];    // número fora da lista: ignora
  const nome = ((j.contacts || [])[0] || {}).profile?.name;
  canal = 'whatsapp';
  responder_para = m.from;
  origem = 'WhatsApp' + (nome ? ' (' + nome + ')' : '');
  encaminhada = !!(m.context && (m.context.forwarded || m.context.frequently_forwarded));
  // Mensagem encaminhada não traz a data em que o cliente escreveu: a referência é o encaminhamento
  const enviado = DateTime.fromSeconds(Number(m.timestamp) || 0);
  referencia = (Number(m.timestamp) && enviado.isValid ? enviado : DateTime.now()).setZone(CONFIG.fuso);
  if (m.type === 'text') {
    texto = (m.text && m.text.body) || '';
  } else {
    const tipos = { audio: 'um áudio', image: 'uma imagem', document: 'um arquivo', video: 'um vídeo', sticker: 'uma figurinha' };
    erro = 'Recebi ' + (tipos[m.type] || 'uma mensagem que não é texto') +
      ', mas por enquanto só leio mensagens de texto. Mande o pedido escrito (ou encaminhe a mensagem de texto do cliente).';
  }
  if (!erro && !texto.trim()) erro = 'A mensagem chegou vazia.';
} else if (j['Texto do pedido']) {
  // Veio do formulário (texto colado à mão)
  texto = j['Texto do pedido'];
  canal = 'formulario';
  origem = 'Formulário (' + (j['Origem'] || 'colado') + ')';
  referencia = DateTime.now().setZone(CONFIG.fuso);
} else {
  // Veio do Gmail
  const corpo = j.text || j.textPlain || j.snippet || '';
  texto = 'Assunto: ' + (j.subject || '') + '\nDe: ' + ((j.from && j.from.text) || '') + '\n\n' + corpo;
  canal = 'email';
  origem = 'E-mail';
  // Datas relativas ("amanhã", "próxima terça") contam a partir do ENVIO do e-mail, não de agora
  const enviado = j.date ? DateTime.fromJSDate(new Date(j.date)) : null;
  referencia = (enviado && enviado.isValid ? enviado : DateTime.now()).setZone(CONFIG.fuso);
}

return [{
  json: {
    ...CONFIG,
    texto,
    origem,
    canal,             // whatsapp | email | formulario: define por onde vai a resposta
    responder_para,    // número do WhatsApp de quem mandou o pedido
    encaminhada,
    erro,              // preenchido quando a mensagem não dá para ler (áudio, imagem...)
    referencia_iso: referencia.toISO(),
    referencia_extenso: referencia.setLocale('pt-BR').toFormat("cccc, dd 'de' LLLL 'de' yyyy, HH:mm"),
  },
}];

const p = $input.first().json;

const SYSTEM = `Você extrai dados de pedidos de serviço recebidos por uma empresa que atua com licitações públicas (ex.: representar o cliente em sessão de pregão, entregar documentos/envelopes, fazer visita técnica, enviar proposta, protocolar recurso).

Leia a mensagem e preencha o esquema. Regras:
- Nunca invente. Campo sem informação = string vazia.
- "data" no formato AAAA-MM-DD; horas em HH:MM (24h), horário de Brasília.
- Datas no formato brasileiro: 05/11 é 5 de novembro. Nunca leia como mês/dia.
- Datas relativas ("amanhã", "sexta que vem", "daqui a 3 dias") devem ser resolvidas a partir da DATA DE REFERÊNCIA informada, consultando o CALENDÁRIO fornecido. Marque data_relativa=true e explique em "ambiguidades" como resolveu.
- Data com dia e mês escritos (ex.: "05/11", "5 de novembro") NÃO é relativa, mesmo sem o ano: data_relativa=false. Se o ano não estiver escrito, use a próxima ocorrência a partir da data de referência. Ano omitido é normal: sozinho, não reduz a confiança e não vai em "ambiguidades".
- "trecho_da_data": copie LITERALMENTE o trecho da mensagem de onde tirou a data e a hora.
- "dia_da_semana_citado": se a mensagem escrever um dia da semana junto da data principal, copie-o (ex.: "segunda-feira"). Se não escrever, deixe vazio. Não calcule o dia da semana você mesmo.
- Mensagens de licitação costumam ter várias datas (impugnação, abertura de propostas, sessão de disputa, entrega). A data principal é aquela em que a empresa precisa EXECUTAR o serviço pedido. Liste as demais em "outras_datas". Se não for possível saber qual é a principal, diga isso em "ambiguidades" e use confianca "baixa".
- "confianca": "alta" somente se dia, mês e hora estão escritos explicitamente (o ano pode faltar) e não há conflito; "media" se algo foi deduzido; "baixa" se há dúvida real.
- "resumo": título curto para a agenda, ex.: "Sessão Pregão 45/2026 – Pref. de Campinas".
- eh_pedido_de_servico=false se a mensagem não pede nenhum serviço com data (propaganda, conversa, aviso genérico).`;

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    eh_pedido_de_servico: { type: 'boolean' },
    resumo: { type: 'string' },
    tipo_servico: { type: 'string' },
    orgao: { type: 'string' },
    numero_processo: { type: 'string' },
    local: { type: 'string' },
    contato: { type: 'string' },
    data: { type: 'string' },
    hora_inicio: { type: 'string' },
    hora_fim: { type: 'string' },
    trecho_da_data: { type: 'string' },
    dia_da_semana_citado: { type: 'string' },
    data_relativa: { type: 'boolean' },
    outras_datas: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          data: { type: 'string' },
          hora: { type: 'string' },
          descricao: { type: 'string' },
        },
        required: ['data', 'hora', 'descricao'],
      },
    },
    confianca: { type: 'string', enum: ['alta', 'media', 'baixa'] },
    ambiguidades: { type: 'array', items: { type: 'string' } },
    observacoes: { type: 'string' },
  },
  required: [
    'eh_pedido_de_servico', 'resumo', 'tipo_servico', 'orgao', 'numero_processo', 'local',
    'contato', 'data', 'hora_inicio', 'hora_fim', 'trecho_da_data', 'dia_da_semana_citado',
    'data_relativa', 'outras_datas', 'confianca', 'ambiguidades', 'observacoes',
  ],
};

// Calendário pronto: modelos erram conta de dia da semana; assim só precisam consultar
const ref = DateTime.fromISO(p.referencia_iso, { setZone: true });
const calendario = [];
for (let i = 0; i < 60; i++) {
  const dia = ref.plus({ days: i });
  calendario.push(dia.setLocale('pt-BR').toFormat('cccc dd/MM/yyyy') + (i === 0 ? ' (hoje)' : i === 1 ? ' (amanhã)' : ''));
}

const body = {
  model: 'openai/gpt-oss-120b',
  reasoning_effort: 'medium',
  max_completion_tokens: 4000,
  response_format: {
    type: 'json_schema',
    json_schema: { name: 'pedido', strict: true, schema: SCHEMA },
  },
  messages: [
    { role: 'system', content: SYSTEM },
    {
      role: 'user',
      content:
        'DATA DE REFERÊNCIA (envio da mensagem): ' + p.referencia_extenso + ' (' + p.referencia_iso + ')\n' +
        'ORIGEM: ' + p.origem + '\n\n' +
        'CALENDÁRIO (use para resolver datas relativas e dias da semana, não calcule de cabeça):\n' +
        calendario.join('\n') + '\n\n<mensagem>\n' + p.texto + '\n</mensagem>',
    },
  ],
};

return [{ json: { body } }];

const resp = $input.first().json;
const p = $('Normalizar entrada').first().json;
const fuso = p.fuso;
const agora = DateTime.now().setZone(fuso);

const falha = (erro, dados) => [{ json: { erro, dados: dados || null } }];

// ---- 1. Ler a resposta da IA ----
let d;
try {
  if (resp.error) throw new Error('Falha na chamada à IA: ' + JSON.stringify(resp.error).slice(0, 400));
  const escolha = (resp.choices || [])[0];
  if (!escolha || !escolha.message) throw new Error('A IA não devolveu resposta.');
  if (escolha.message.refusal) throw new Error('A IA se recusou a processar a mensagem.');
  if (escolha.finish_reason === 'length') throw new Error('A resposta da IA veio cortada (limite de tokens).');
  if (!escolha.message.content) throw new Error('A resposta da IA não trouxe texto.');
  d = JSON.parse(escolha.message.content);
} catch (e) {
  return falha(e.message);
}

if (!d.eh_pedido_de_servico) {
  return falha('Não encontrei um pedido de serviço com data nesta mensagem. Se for um pedido, agende manualmente ou mande de novo com a data e a hora escritas.', d);
}

// ---- 2. Data e hora ----
const dia = DateTime.fromISO(d.data || '', { zone: fuso });
if (!d.data || !dia.isValid) {
  return falha('Não consegui identificar a data do serviço. Trecho encontrado: "' + (d.trecho_da_data || '—') + '"', d);
}

const hhmm = s => {
  const m = /^(\d{1,2}):(\d{2})$/.exec((s || '').trim());
  return m && +m[1] < 24 && +m[2] < 60 ? { hour: +m[1], minute: +m[2] } : null;
};
const hi = hhmm(d.hora_inicio);
const hf = hhmm(d.hora_fim);

// Sem botão de confirmação: o evento nasce verde. Qualquer dúvida real sobre a data
// o deixa vermelho, com "⚠️ VERIFICAR" no título. Avisos só informativos não mudam a cor.
const alertas = [];
let verificar = false;
const duvida = msg => { alertas.push(msg); verificar = true; };

let inicio, fim, diaInteiro = false;
if (hi) {
  inicio = dia.set({ ...hi, second: 0, millisecond: 0 });
  fim = hf ? dia.set({ ...hf, second: 0, millisecond: 0 }) : inicio.plus({ hours: p.duracao_padrao_horas });
  if (fim <= inicio) fim = inicio.plus({ hours: p.duracao_padrao_horas });
} else {
  diaInteiro = true;
  inicio = dia.startOf('day');
  fim = inicio.plus({ days: 1 });
  duvida('HORÁRIO NÃO ENCONTRADO: criei como evento de dia inteiro. Os lembretes contam a partir da meia-noite. Ajuste a hora na agenda.');
}

// ---- 3. Checagens determinísticas (não dependem da IA) ----
const semAcento = s => (s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const DIAS = { seg: 1, ter: 2, qua: 3, qui: 4, sex: 5, sab: 6, dom: 7 };
const citado = DIAS[semAcento(d.dia_da_semana_citado).slice(0, 3)];
const diaSemanaReal = inicio.setLocale('pt-BR').toFormat('cccc');
if (citado && citado !== inicio.weekday) {
  duvida('CONFLITO DE DATA: a mensagem diz "' + d.dia_da_semana_citado + '", mas ' +
    inicio.toFormat('dd/MM/yyyy') + ' cai numa ' + diaSemanaReal + '. Uma das duas informações está errada. CONFIRA COM O CLIENTE.');
}
if (inicio < agora) duvida('A data identificada JÁ PASSOU (' + inicio.toFormat('dd/MM/yyyy HH:mm') + ').');
// 6 meses, não 1 ano: com o ano omitido, uma data que acabou de passar ("05/10" lido em 13/10)
// vira a do ano seguinte, a ~11 meses. Serviço de licitação raramente é marcado com 6 meses de antecedência.
if (inicio > agora.plus({ days: 180 })) duvida('A data está a mais de 6 meses de distância. Confira o ano.');
const horasAte = inicio.diff(agora, 'hours').hours;
if (horasAte >= 0 && horasAte < 48) alertas.push('URGENTE: faltam só ' + Math.floor(horasAte) + 'h.');
if (d.confianca !== 'alta') duvida('Confiança da IA: ' + d.confianca.toUpperCase() + '.');
// A IA às vezes marca "relativa" só porque o ano não foi escrito ("05/11 às 10:00"). Com dia e mês
// escritos no trecho, a data não é relativa, e o alerta seria ruído que ensina a Naty a ignorar alertas.
const temDiaEMes = /\d{1,2}\s*\/\s*\d{1,2}|\d{1,2}º?\s+de\s+(jan|fev|mar|abr|mai|jun|jul|ago|set|out|nov|dez)/.test(semAcento(d.trecho_da_data));
if (d.data_relativa && !temDiaEMes) {
  if (p.encaminhada) {
    // O WhatsApp não diz quando o cliente escreveu: "amanhã" de 3 dias atrás vira o amanhã de hoje
    duvida('Mensagem ENCAMINHADA com data relativa: o WhatsApp não informa quando o cliente escreveu, então "' +
      (d.trecho_da_data || 'a data') + '" foi calculado a partir de quando você encaminhou (' + p.referencia_extenso +
      '). Se o cliente escreveu em outro dia, a data está errada.');
  } else {
    alertas.push('A data foi escrita de forma relativa ("amanhã", "sexta que vem"...) e foi calculada a partir de ' + p.referencia_extenso + '.');
  }
}
for (const a of d.ambiguidades || []) duvida(a);

// ---- 4. Evento ----
const resumo = d.resumo || d.tipo_servico || 'Serviço de licitação';
const convidados = [...new Set((p.emails_equipe || []).map(e => String(e).trim().toLowerCase()).filter(e => e.includes('@')))];
const outras = (d.outras_datas || []).map(o => '• ' + o.descricao + ': ' + o.data + (o.hora ? ' ' + o.hora : ''));

const descricao = [
  'Serviço: ' + (d.tipo_servico || '—'),
  'Órgão: ' + (d.orgao || '—'),
  'Processo/Edital: ' + (d.numero_processo || '—'),
  'Local: ' + (d.local || '—'),
  'Contato: ' + (d.contato || '—'),
  '',
  'Trecho original da data: "' + (d.trecho_da_data || '—') + '"',
  outras.length ? '\nOutras datas na mensagem:\n' + outras.join('\n') : '',
  alertas.length ? '\n⚠️ ALERTAS:\n- ' + alertas.join('\n- ') : '',
  d.observacoes ? '\nObservações: ' + d.observacoes : '',
  '',
  'Origem: ' + p.origem,
  '--- Mensagem original ---',
  p.texto.length > 6000 ? p.texto.slice(0, 6000) + '\n[...texto completo na mensagem original]' : p.texto,
].join('\n');

const evento = {
  summary: (verificar ? '⚠️ VERIFICAR: ' : '') + resumo,
  location: d.local || undefined,
  description: descricao,
  colorId: verificar ? '11' : '10', // vermelho = conferir a data; verde = ok
  extendedProperties: { private: { naty_bot: '1' } }, // marca usada pelo workflow de lembretes
  start: diaInteiro ? { date: inicio.toISODate() } : { dateTime: inicio.toISO({ suppressMilliseconds: true }), timeZone: fuso },
  end: diaInteiro ? { date: fim.toISODate() } : { dateTime: fim.toISO({ suppressMilliseconds: true }), timeZone: fuso },
  // Alarmes no celular de quem é dono da agenda. Os e-mails de lembrete saem do workflow de lembretes.
  reminders: {
    useDefault: false,
    overrides: [
      { method: 'popup', minutes: 2880 }, // 2 dias
      { method: 'popup', minutes: 1440 }, // 1 dia
      { method: 'popup', minutes: 720 },  // 12 horas
      { method: 'popup', minutes: 360 },  // 6 horas
    ],
  },
};
// Convidados recebem o convite do Google e os lembretes por e-mail
if (convidados.length) evento.attendees = convidados.map(email => ({ email }));

// ---- 5. Resposta para quem mandou o pedido (WhatsApp ou e-mail) ----
const dataExtenso = inicio.setLocale('pt-BR').toFormat("cccc, dd 'de' LLLL 'de' yyyy").toUpperCase() +
  (diaInteiro ? ' (SEM HORÁRIO)' : ' às ' + inicio.toFormat('HH:mm'));

// Mesmo conteúdo nos dois formatos: no WhatsApp, *negrito*; no e-mail, HTML com o texto do cliente escapado
function resposta(b, t) {
  return [
    verificar ? '⚠️ ' + b('Agendei, mas CONFIRA a data') : '✅ ' + b('Agendado'),
    b(resumo),
    '',
    '📅 ' + b(dataExtenso),
    t('A mensagem diz: "' + (d.trecho_da_data || '—') + '"'),
    alertas.length ? '\n⚠️ ' + b('ATENÇÃO:') + '\n' + alertas.map(a => '• ' + t(a)).join('\n') : '',
    '',
    t('Serviço: ' + (d.tipo_servico || '—')),
    t('Órgão: ' + (d.orgao || '—')),
    t('Processo: ' + (d.numero_processo || '—')),
    t('Local: ' + (d.local || '—')),
    t('Contato: ' + (d.contato || '—')),
    outras.length ? '\n' + t('Outras datas na mensagem:') + '\n' + outras.map(t).join('\n') : '',
    convidados.length ? '\n' + t('Convite e lembretes por e-mail para: ' + convidados.join(', ')) : '',
    '',
    t(verificar
      ? 'Na agenda o evento ficou VERMELHO, com "VERIFICAR" no título. Confira a data e corrija direto no evento se precisar; os lembretes se ajustam sozinhos.'
      : 'Se algo estiver errado, corrija direto no evento; os lembretes se ajustam sozinhos.'),
  ].join('\n');
}
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let resposta_whatsapp = resposta(s => '*' + s + '*', s => s);
if (resposta_whatsapp.length > 3800) resposta_whatsapp = resposta_whatsapp.slice(0, 3700) + '\n[...]'; // limite do WhatsApp: 4096
const resposta_html = resposta(s => '<b>' + esc(s) + '</b>', esc).replace(/\n/g, '<br>');

return [{
  json: {
    erro: '',
    resumo,
    verificar,
    evento,
    resposta_whatsapp,
    resposta_html,
    assunto_email: (verificar ? '⚠️ CONFIRA: ' : '✅ Agendado: ') + resumo + ' — ' + inicio.toFormat('dd/MM') + (diaInteiro ? '' : ' ' + inicio.toFormat('HH:mm')),
    alertas,
    dados: d,
  },
}];

// Monta o aviso "NÃO agendado", venha a falha de onde vier:
// mensagem ilegível (áudio, imagem), IA, ou erro do Google Agenda ao criar o evento.
const j = $input.first().json;
const p = $('Normalizar entrada').first().json;

const motivo = j.erro || ('Erro ao criar o evento no Google Agenda: ' + JSON.stringify(j.error || j).slice(0, 300));
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

return [{
  json: {
    motivo,
    texto_whatsapp: '🚨 *NÃO agendei este pedido.*\n\n' + motivo + '\n\nSe for um pedido, coloque na agenda manualmente.',
    assunto_email: '🚨 Pedido NÃO agendado — agende manualmente',
    html_email:
      '<p><b>O robô não conseguiu agendar este pedido.</b> Coloque na agenda manualmente.</p>' +
      '<p>Motivo: ' + esc(motivo) + '</p>' +
      '<p>Origem: ' + esc(p.origem) + '</p><hr>' +
      '<p>' + esc(p.texto.slice(0, 6000)).replace(/\n/g, '<br>') + '</p>',
  },
}];
